<script setup lang="ts">
import {onMounted,ref} from 'vue'
import type {AccountSummary,ControlRequest,Page,ShtongApi} from '@shtong/api-sdk'
import {localTime,zh} from '@shtong/web-shared'
import {useAction} from '../composables/useAction'
import ActionFeedback from './ActionFeedback.vue'
import AppDialog from './AppDialog.vue'
const props=defineProps<{api:ShtongApi}>(),{busy,error,notice,run}=useAction()
const rows=ref<ControlRequest[]>([]),reason=ref('核对申请后确认'),next=ref<string>(),names=ref<Record<string,string>>({}),pending=ref<{control:ControlRequest;action:'approve'|'reject'}>()
async function load(more=false){const result=await props.api.request<Page<ControlRequest>>(`/system/control-requests${more&&next.value?'?cursor='+encodeURIComponent(next.value):''}`);rows.value=more?[...rows.value,...result.items]:result.items;next.value=result.nextCursor||undefined;await Promise.all([...new Set(result.items.map(item=>item.requestedBy))].map(async id=>{if(names.value[id])return;try{const account=await props.api.request<AccountSummary>(`/system/accounts/${id}`);names.value[id]=`${account.displayName}（${account.loginName}）`}catch{names.value[id]='账户信息暂不可用'}}))}
function decide(){void run(async()=>{if(!pending.value)return;const {control,action}=pending.value;const result=await props.api.request<ControlRequest>(`/system/control-requests/${control.id}/${action}`,{method:'POST',body:JSON.stringify({expectedVersion:control.version,reason:reason.value})});notice.value=`申请${zh(result.state)}`;pending.value=undefined;await load()})}
onMounted(()=>run(()=>load()))
</script>
<template><section class="view"><header class="page-header"><h1>安全复核</h1><button class="secondary" :disabled="busy" @click="run(()=>load())">刷新</button></header><ActionFeedback :error="error" :notice="notice" :busy="busy"/><div class="record-list"><article v-for="control in rows" :key="control.id"><div><strong>{{zh(control.commandType)}}</strong><p>{{control.reason}} · 涉及 {{control.targetCount}} 人</p><small>发起人：{{names[control.requestedBy]}}</small><small>{{localTime(control.requestedAt)}}</small></div><span class="status" :class="control.state.toLowerCase()">{{zh(control.state)}}</span><div class="row-actions"><button class="secondary" :disabled="busy||control.state!=='PENDING'" @click="error='';pending={control,action:'reject'}">拒绝</button><button class="primary" :disabled="busy||control.state!=='PENDING'" @click="error='';pending={control,action:'approve'}">同意</button></div></article><p v-if="!rows.length" class="empty">暂无复核申请</p><button v-if="next" class="secondary" :disabled="busy" @click="run(()=>load(true))">更多申请</button></div><AppDialog v-if="pending" :title="pending.action==='approve'?'确认同意申请':'确认拒绝申请'" :busy="busy" @close="pending=undefined"><form @submit.prevent="decide"><p>{{zh(pending.control.commandType)}} · 涉及 {{pending.control.targetCount}} 人</p><p>申请原因：{{pending.control.reason}}</p><label>复核意见<input v-model="reason" required minlength="2" maxlength="500"></label><ActionFeedback :error="error"/><button class="primary" :disabled="busy">{{pending.action==='approve'?'同意并执行':'拒绝申请'}}</button></form></AppDialog></section></template>
